const listPublishedMeals = `-- name: ListPublishedMeals :many


SELECT
    m.id, m.slug, m.name, m.summary, m.prep_minutes, m.cook_minutes, m.servings, m.protein,
    m.dietary_tags, m.allergens, m.allergen_status, m.is_demo, m.published_at,
    c.slug AS category_slug, c.name AS category_name,
    ch.slug AS chef_slug, ch.display_name AS chef_name,
    img.src AS image_src, img.alt AS image_alt, img.width AS image_width, img.height AS image_height,
    n.calories AS calories, n.protein_g AS protein_g,
    count(*) OVER () AS total
FROM meals m
JOIN meal_categories c ON c.id = m.category_id
LEFT JOIN chef_profiles ch ON ch.id = m.chef_id AND ch.status = 'published' AND (NOT ch.is_demo OR $1::bool)
LEFT JOIN meal_images img ON img.meal_id = m.id AND img.position = 0
LEFT JOIN meal_nutrition n ON n.meal_id = m.id AND n.status = 'verified'
WHERE m.status = 'published'
  AND (NOT m.is_demo OR $1::bool)
  AND ($2::text IS NULL OR c.slug = $2::text)
  AND NOT EXISTS (
      SELECT 1 FROM unnest($3::text[]) AS g(alts)
      WHERE NOT (m.dietary_tags && string_to_array(g.alts, '|')))
  AND ($4::int IS NULL OR m.prep_minutes + m.cook_minutes <= $4::int)
  AND ($5::text IS NULL OR m.protein = $5::text)
  AND ($6::text IS NULL OR ch.slug = $6::text)
  AND ($7::text IS NULL
       OR (setweight(to_tsvector('english', m.name), 'A') ||
           setweight(to_tsvector('english', m.summary), 'B') ||
           setweight(to_tsvector('english', m.description), 'C'))
          @@ websearch_to_tsquery('english', $7::text)
       OR m.name ILIKE '%' || $8::text || '%')
  AND (cardinality($9::text[]) = 0
       OR (m.allergen_status = 'declared' AND NOT (m.allergens && $9::text[])))
  AND (cardinality($10::uuid[]) = 0 OR m.id = ANY ($10::uuid[]))
ORDER BY
    CASE WHEN $11::text = 'quickest' THEN m.prep_minutes + m.cook_minutes END ASC,
    CASE WHEN $11::text = 'name' THEN m.name END ASC,
    m.published_at DESC, m.id
LIMIT $13 OFFSET $12
`

type ListPublishedMealsParams struct {
	AllowDemo        bool
	Category         *string
	DietGroups       []string
	MaxMinutes       *int32
	Protein          *string
	Chef             *string
	Search           *string
	SearchLike       *string
	ExcludeAllergens []string
	Ids              []string
	Sort             string
	Off              int32
	Lim              int32
}

type ListPublishedMealsRow struct {
	ID             string
	Slug           string
	Name           string
	Summary        string
	PrepMinutes    int16
	CookMinutes    int16
	Servings       int16
	Protein        *string
	DietaryTags    []string
	Allergens      []string
	AllergenStatus string
	IsDemo         bool
	PublishedAt    *time.Time
	CategorySlug   string
	CategoryName   string
	ChefSlug       *string
	ChefName       *string
	ImageSrc       *string
	ImageAlt       *string
	ImageWidth     *int32
	ImageHeight    *int32
	Calories       *int16
	ProteinG       *float64
	Total          int64
}

// Queries for the catalogue (sqlc).
//
// Public queries return only published meals, and demo content only when
// @allow_demo is true (CATALOG_DEMO_ENABLED). Nutrition is joined only when
// verified. A meal's primary photograph is the one at position 0.
// ---------------------------------------------------------------- public
// diet_groups: each element is one requirement, written as the tags that
// satisfy it separated by "|" ("vegetarian|vegan"); a meal must match every
// requirement. exclude_allergens drops meals that declare any of them, and
// meals whose allergens are not yet declared at all.
func (q *Queries) ListPublishedMeals(ctx context.Context, arg ListPublishedMealsParams) ([]ListPublishedMealsRow, error) {
	rows, err := q.db.Query(ctx, listPublishedMeals,
		arg.AllowDemo,
		arg.Category,
		arg.DietGroups,
		arg.MaxMinutes,
		arg.Protein,
		arg.Chef,
		arg.Search,
		arg.SearchLike,
		arg.ExcludeAllergens,
		arg.Ids,
		arg.Sort,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPublishedMealsRow{}
	for rows.Next() {
		var i ListPublishedMealsRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.Summary,
			&i.PrepMinutes,
			&i.CookMinutes,
			&i.Servings,
			&i.Protein,
			&i.DietaryTags,
			&i.Allergens,
			&i.AllergenStatus,
			&i.IsDemo,
			&i.PublishedAt,
			&i.CategorySlug,
			&i.CategoryName,
			&i.ChefSlug,
			&i.ChefName,
			&i.ImageSrc,
			&i.ImageAlt,
			&i.ImageWidth,
			&i.ImageHeight,
			&i.Calories,
			&i.ProteinG,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

